function pl(w,  n,c2,last){
  n=length(w); if(n==0) return w;
  last=substr(w,n,1);
  if(n>=2 && substr(w,n-1,2)=="es") return w;
  if(last=="y"){ if(n>=2){ c2=substr(w,n-1,1); if(index("aeiou",c2)==0) return substr(w,1,n-1) "ies"; } return w "s"; }
  if(last=="s") return w "es";
  if(n>=2 && (substr(w,n-1,2)=="ch"||substr(w,n-1,2)=="sh")) return w "es";
  return w "s";
}
BEGIN{FS="\t"}
{ e=pl($1); if(e!=$2) print "MISMATCH\t"$1"\t"$2"\tpred="e; else ok++ }
END{ print "OK="ok }
