BEGIN{FS="\t"; OFS="\t"}
function pred(w,  n,last,prev){
  n=length(w); last=substr(w,n,1); prev=(n>1?substr(w,n-1,1):"")
  if(last=="y" && n>1 && prev !~ /^[aeiou]$/) return substr(w,1,n-1) "ies"
  if(substr(w,n-1,2)=="es") return w
  if(last=="s" || substr(w,n-1,2)=="ch" || substr(w,n-1,2)=="sh") return w "es"
  return w "s"
}
{ p=pred($1); if(p!=$2) print $1, $2, p }
